"""Runs the 5 agents in order, yielding progress events so the UI can show real per-agent status."""

from __future__ import annotations

import logging
import time
from collections.abc import Iterator

from . import agents
from .db import LEGACY_WORKSPACE_ID, new_id, utcnow
from .entitlements import AnalysisOptions
from .regulations import load_regulation_pair_by_id
from .services import Services

logger = logging.getLogger(__name__)

DISCLAIMER = (
    "This action plan was generated by an automated multi-agent AI system for informational purposes only and "
    "does not constitute legal advice. Verify all findings with licensed legal counsel or an accredited VAT "
    "practitioner before acting on them."
)

AGENT_NAMES = {1: "Watcher", 2: "Retriever", 3: "Impact Analyzer", 4: "Action Plan Generator", 5: "Critic / Verifier"}


class NotFoundError(LookupError):
    pass


def load_inputs(
    svc: Services, company_profile_id: str, document_id: str, workspace_id: str | None = None
) -> tuple[dict, dict]:
    company = svc.db.get_company(company_profile_id, workspace_id)
    if company is None:
        raise NotFoundError("Company profile not found.")
    document = svc.db.get_document(document_id, workspace_id)
    if document is None or document["company_profile_id"] != company_profile_id:
        raise NotFoundError("Document not found for this company profile.")
    return company, document


def run_pipeline(
    svc: Services,
    company: dict,
    document: dict,
    options: AnalysisOptions | None = None,
    workspace_id: str = LEGACY_WORKSPACE_ID,
    regulation_id: str | None = None,
) -> Iterator[dict]:
    """Yields `agent_started` / `agent_completed` events and finally `completed` (with the plan) or `error`."""
    svc.require_llm()
    pipeline_start = time.perf_counter()
    agent = 0

    def started(n: int) -> dict:
        nonlocal agent
        agent = n
        return {"type": "agent_started", "agent": n, "name": AGENT_NAMES[n]}

    def completed(n: int, began: float, detail: str) -> dict:
        return {
            "type": "agent_completed",
            "agent": n,
            "name": AGENT_NAMES[n],
            "detail": detail,
            "duration_ms": int((time.perf_counter() - began) * 1000),
        }

    try:
        pair = load_regulation_pair_by_id(svc.db, regulation_id, svc.settings.regulation_dir)
        t = time.perf_counter()
        yield started(1)
        watcher, cached = agents.run_watcher(svc, pair=pair, regulation_id=regulation_id)
        yield completed(
            1,
            t,
            f"{len(watcher['changed_clauses'])} changed clauses, {len(watcher['obligations'])} obligations extracted"
            + (" (cached)" if cached else ""),
        )

        t = time.perf_counter()
        yield started(2)
        retrieved = agents.run_retriever(svc, document["id"], watcher)
        sections = list(dict.fromkeys(c["section"] for c in retrieved))
        yield completed(2, t, f"{len(retrieved)} SOP chunks retrieved from {len(sections)} sections: " + ", ".join(sections[:4]))

        t = time.perf_counter()
        yield started(3)
        analysis = agents.run_analyzer(svc, company, watcher, retrieved, pair=pair)
        yield completed(
            3, t, f"{len(analysis['findings'])} findings, impact {analysis['impact_score']}/100, urgency {analysis['urgency']}"
        )

        t = time.perf_counter()
        # Agent 4: skipped entirely (no LLM call) when action_plans == off
        skip_agent_4 = options is not None and options.action_plans_level == "off"
        if skip_agent_4:
            generated = {"policy_draft": [], "technical_fixes": []}
            yield started(4)
            yield completed(4, t, "Skipped by plan entitlements (action_plans=off)")
        else:
            yield started(4)
            generated = agents.run_generator(svc, company, watcher, analysis, retrieved)
            yield completed(
                4, t, f"{len(generated['policy_draft'])} policy amendments, {len(generated['technical_fixes'])} technical fixes"
            )

        t = time.perf_counter()
        yield started(5)
        findings = agents.run_critic(svc, document, analysis, pair=pair)
        flagged = sum(1 for f in findings if f["flagged_for_review"])
        yield completed(5, t, f"{len(findings) - flagged}/{len(findings)} citations verified, {flagged} flagged for review")

        raw_plan = {
            "id": new_id(),
            "company": company["company_name"],
            "regulation": watcher["title"],
            "change_summary": watcher["change_summary"],
            "impact_score": analysis["impact_score"],
            "urgency": analysis["urgency"],
            "findings": findings,
            "policy_draft": generated["policy_draft"],
            "technical_fixes": generated["technical_fixes"],
            "disclaimer": DISCLAIMER,
            "document_name": document["filename"],
            "regulation_version_hash": watcher["version_hash"],
            "model": svc.require_llm().model_name,
            "created_at": utcnow(),
        }

        # Apply tier-based gating via AnalysisOptions
        final_plan = options.apply(raw_plan) if options is not None else raw_plan

        svc.db.save_action_plan(final_plan, company["id"], document["id"], workspace_id=workspace_id)
        yield {
            "type": "completed",
            "plan_id": final_plan["id"],
            "plan": final_plan,
            "duration_ms": int((time.perf_counter() - pipeline_start) * 1000),
        }
    except Exception as exc:
        logger.exception("Pipeline failed at agent %s", agent)
        yield {"type": "error", "agent": agent or None, "message": str(exc) or exc.__class__.__name__}

